:root {
  --bg: #0b1020;
  --panel: #111830;
  --card: #141b2e;
  --border: #2a3550;
  --text: #e2e8f0;
  --muted: #7c8db0;
  --accent: #38bdf8;
  --good: #4ade80;
  --warn: #fbbf24;
  --bad: #f87171;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: "PingFang SC", "Microsoft YaHei", system-ui, -apple-system, sans-serif;
  font-size: 14px;
}

.app { min-height: 100vh; display: flex; flex-direction: column; }

.app-header {
  padding: 14px 24px;
  border-bottom: 1px solid var(--border);
  background: linear-gradient(90deg, #0d1430, #111830);
}
.app-header h1 { margin: 0; font-size: 20px; }
.app-header p { margin: 4px 0 0; color: var(--muted); font-size: 12px; }

.layout { display: flex; flex: 1; align-items: flex-start; }

.sidebar {
  width: 400px;
  flex-shrink: 0;
  padding: 16px;
  border-right: 1px solid var(--border);
  position: sticky;
  top: 0;
  max-height: calc(100vh - 60px);
  overflow-y: auto;
}

.content { flex: 1; padding: 16px 24px; min-width: 0; }

/* ---------- 配置面板 ---------- */
.config-panel section {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 12px 14px;
  margin-bottom: 12px;
}
.config-panel h2 {
  margin: 0 0 10px;
  font-size: 14px;
  color: var(--accent);
}
.config-panel h2 small { color: var(--muted); font-weight: normal; margin-left: 6px; }

.row { display: flex; gap: 6px; align-items: center; margin-bottom: 6px; flex-wrap: wrap; }
.grow { flex: 1; }

.grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.grid2 label { display: flex; flex-direction: column; gap: 4px; font-size: 12px; color: var(--muted); }

input, select {
  background: #0d1428;
  border: 1px solid var(--border);
  color: var(--text);
  border-radius: 6px;
  padding: 5px 8px;
  font-size: 13px;
}
input:focus, select:focus { outline: 1px solid var(--accent); }
input[type="color"] { padding: 1px 2px; width: 34px; height: 28px; }
input[type="checkbox"] { accent-color: var(--accent); }

.fuel-row .fuel-name { width: 90px; }
.pump-row .pump-name { width: 110px; }
.chk { display: flex; align-items: center; gap: 3px; font-size: 12px; white-space: nowrap; }

.compact-table { width: 100%; border-collapse: collapse; }
.compact-table th { font-size: 11px; color: var(--muted); font-weight: normal; padding: 2px; }
.compact-table td { padding: 2px; text-align: center; }

.icon-btn {
  background: none; border: none; color: var(--muted); cursor: pointer; font-size: 12px;
}
.icon-btn:hover { color: var(--bad); }

.ghost-btn {
  background: none; border: 1px dashed var(--border); color: var(--muted);
  border-radius: 6px; padding: 4px 10px; cursor: pointer; font-size: 12px; margin-top: 4px;
}
.ghost-btn:hover { color: var(--accent); border-color: var(--accent); }

.run-btn {
  width: 100%;
  padding: 12px;
  font-size: 16px;
  font-weight: 600;
  color: #06121f;
  background: linear-gradient(90deg, #38bdf8, #4ade80);
  border: none;
  border-radius: 10px;
  cursor: pointer;
}
.run-btn:disabled { opacity: 0.5; cursor: wait; }

.error-box {
  margin-top: 10px; padding: 10px 12px; border-radius: 8px;
  background: #3b1520; border: 1px solid var(--bad); color: #fecaca; font-size: 13px;
}

.muted { color: var(--muted); font-size: 12px; }

.empty-state {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  height: 60vh; color: var(--muted); text-align: center;
}
.empty-icon { font-size: 56px; margin-bottom: 12px; }

/* ---------- 结果区 ---------- */
.dashboard { display: flex; flex-direction: column; gap: 14px; }

.card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 14px 16px;
}
.card h3 { margin: 0 0 12px; font-size: 15px; }

.kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 10px;
}
.kpi-card {
  background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 12px 14px;
}
.kpi-bad { border-color: var(--bad); }
.kpi-label { font-size: 12px; color: var(--muted); }
.kpi-value { font-size: 22px; font-weight: 700; margin: 4px 0; }
.kpi-sub { font-size: 11px; color: var(--muted); display: flex; gap: 6px; flex-wrap: wrap; }

.delta { font-size: 11px; }
.delta.good { color: var(--good); }
.delta.bad { color: var(--bad); }
.delta.flat { color: var(--muted); }

.two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
@media (max-width: 1100px) { .two-col { grid-template-columns: 1fr; } }

.rec-list { margin: 0; padding-left: 18px; display: flex; flex-direction: column; gap: 6px; }
.rec-list li { line-height: 1.5; }

/* 人力桶 */
.bucket-row { display: flex; gap: 3px; align-items: flex-end; overflow-x: auto; padding-bottom: 4px; }
.bucket-cell { display: flex; flex-direction: column; align-items: center; gap: 3px; min-width: 34px; }
.bucket-bar { width: 22px; background: var(--good); border-radius: 3px 3px 0 0; }
.bucket-bar.bucket-short { background: var(--bad); }
.bucket-label { font-size: 9px; color: var(--muted); white-space: nowrap; }

.legend-line { display: flex; gap: 16px; margin-top: 8px; font-size: 12px; color: var(--muted); }
.swatch { display: inline-block; width: 10px; height: 10px; border-radius: 2px; margin-right: 4px; }
.sw-ok { background: var(--good); }
.sw-short { background: var(--bad); }

/* 甘特图 */
.gantt-wrap { display: flex; flex-direction: column; gap: 10px; }
.gantt { width: 100%; }
.util-list { display: flex; flex-direction: column; gap: 6px; }
.util-row { display: flex; align-items: center; gap: 10px; font-size: 12px; }
.util-name { width: 220px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.util-bar-bg { flex: 1; height: 10px; background: #1a2238; border-radius: 5px; overflow: hidden; }
.util-bar { height: 100%; background: var(--accent); border-radius: 5px; }
.util-bar.util-hot { background: var(--bad); }
.util-num { width: 110px; text-align: right; color: var(--muted); }

/* 统计表 */
.stats-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.stats-table th, .stats-table td { padding: 6px 8px; text-align: left; border-bottom: 1px solid var(--border); }
.stats-table th { color: var(--muted); font-weight: normal; font-size: 12px; }
.row-warn td { color: var(--warn); }
.dot { display: inline-block; width: 9px; height: 9px; border-radius: 50%; margin-right: 6px; }

/* 事件日志 */
.filter-row { display: flex; gap: 8px; align-items: center; margin-bottom: 10px; }
.chip {
  background: #0d1428; border: 1px solid var(--border); color: var(--muted);
  border-radius: 999px; padding: 4px 12px; cursor: pointer; font-size: 12px;
}
.chip-active { color: var(--accent); border-color: var(--accent); }

.event-list {
  max-height: 320px; overflow-y: auto; display: flex; flex-direction: column; gap: 4px;
}
.event-item {
  display: flex; gap: 10px; align-items: baseline; padding: 6px 10px;
  background: #0d1428; border-radius: 8px; border-left: 3px solid var(--border); font-size: 13px;
}
.event-item.level-warn { border-left-color: var(--warn); }
.event-item.level-alert { border-left-color: var(--bad); }
.event-time { color: var(--muted); font-variant-numeric: tabular-nums; min-width: 44px; }
.event-msg { line-height: 1.4; }

