import { JSDOM } from "jsdom";
import fs from "fs";
import path from "path";

const DIST = "/workspace/gas-station-sim/frontend/dist";
const html = fs.readFileSync(path.join(DIST, "index.html"), "utf8");
const jsFile = fs.readdirSync(path.join(DIST, "assets")).find((f) => f.endsWith(".js"));
const js = fs.readFileSync(path.join(DIST, "assets", jsFile), "utf8");

const errors = [];
const dom = new JSDOM(html, {
  url: "http://localhost:8000/",
  runScripts: "outside-only",
  pretendToBeVisual: true,
});
const { window } = dom;

//  polyfill jsdom 缺失的浏览器 API
window.fetch = (url, opts) => fetch(new URL(url, "http://localhost:8000"), opts);
window.ResizeObserver = class { observe() {} unobserve() {} disconnect() {} };
window.structuredClone = window.structuredClone ?? ((o) => JSON.parse(JSON.stringify(o)));
window.addEventListener("error", (e) => errors.push("window: " + e.message));

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

try {
  window.eval(js);
} catch (e) {
  errors.push("eval: " + e.message);
}

await sleep(1500); // 等预设加载 + 初次渲染

const bodyText = window.document.body.textContent;
console.log("配置面板渲染:", bodyText.includes("运行模拟") ? "OK" : "FAIL");
console.log("预设已加载:", bodyText.includes("工作日早高峰") || bodyText.includes("载入预设") ? "OK" : "FAIL");

// 点击「运行模拟」
const runBtn = [...window.document.querySelectorAll("button")].find((b) => b.textContent.includes("运行模拟"));
if (!runBtn) {
  errors.push("找不到运行按钮");
} else {
  runBtn.dispatchEvent(new window.MouseEvent("click", { bubbles: true }));
  await sleep(2500); // 等仿真返回 + 图表渲染
  const t = window.document.body.textContent;
  console.log("KPI 卡片:", t.includes("平均等待") && t.includes("达标率") ? "OK" : "FAIL");
  console.log("排队图:", window.document.querySelectorAll(".recharts-area-area").length > 0 ? "OK" : "FAIL(可能是jsdom零尺寸)");
  console.log("甘特图:", window.document.querySelectorAll(".gantt rect").length > 0 ? "OK" : "FAIL");
  console.log("事件日志:", t.includes("增开") || t.includes("事件轨迹") ? "OK" : "FAIL");
  console.log("调度建议:", t.includes("调度建议") ? "OK" : "FAIL");
  console.log("人力桶:", window.document.querySelectorAll(".bucket-bar").length > 0 ? "OK" : "FAIL");
}

console.log(errors.length ? "❌ JS 错误:\n" + errors.join("\n") : "✅ 无 JS 运行时错误");
process.exit(errors.length ? 1 : 0);

