import type { ReactNode } from "react";
import type { SimConfig, SimResult } from "../types";
import { fmtClock } from "../types";

interface Props {
  result: SimResult;
  config: SimConfig;
  prevKpis: Record<string, number> | null;
}

interface Card {
  label: string;
  value: string;
  sub?: string;
  delta?: ReactNode;
  bad?: boolean;
}

function Delta({ cur, prev, invert = false, suffix = "" }: {
  cur: number; prev: number | undefined; invert?: boolean; suffix?: string;
}) {
  if (prev === undefined) return null;
  const d = cur - prev;
  if (Math.abs(d) < 1e-9) return <span className="delta flat">— 持平</span>;
  const good = invert ? d < 0 : d > 0;
  return (
    <span className={`delta ${good ? "good" : "bad"}`}>
      {d > 0 ? "▲" : "▼"} {Math.abs(d).toFixed(1)}{suffix} vs 上次
    </span>
  );
}

export default function KpiCards({ result, config, prevKpis }: Props) {
  const k = result.kpis;
  const cards: Card[] = [
    {
      label: "到站 / 服务车辆",
      value: `${k.arrived} / ${k.served}`,
      sub: k.unserved > 0 ? `⚠ ${k.unserved} 辆未加上油` : "全部完成服务",
      bad: k.unserved > 0,
    },
    {
      label: "平均等待",
      value: `${k.avg_wait} 分`,
      delta: <Delta cur={k.avg_wait} prev={prevKpis?.avg_wait} invert suffix="分" />,
    },
    {
      label: "P95 等待",
      value: `${k.p95_wait} 分`,
      delta: <Delta cur={k.p95_wait} prev={prevKpis?.p95_wait} invert suffix="分" />,
    },
    {
      label: "最大排队",
      value: `${k.max_queue} 辆`,
      sub: `出现在 ${fmtClock(result.open_time, k.max_queue_time)}`,
      delta: <Delta cur={k.max_queue} prev={prevKpis?.max_queue} invert />,
    },
    {
      label: `达标率(≤${config.policy.wait_target}分)`,
      value: `${k.sla_pct}%`,
      delta: <Delta cur={k.sla_pct} prev={prevKpis?.sla_pct} suffix="%" />,
      bad: k.sla_pct < 80,
    },
    {
      label: "员工利用率",
      value: `${Math.round(k.staff_util * 100)}%`,
      sub: `${config.staff_count} 名在岗 · 1人照看${config.policy.staff_pump_coverage}枪`,
    },
  ];
  return (
    <div className="kpi-grid">
      {cards.map((c, i) => (
        <div key={i} className={`kpi-card ${c.bad ? "kpi-bad" : ""}`}>
          <div className="kpi-label">{c.label}</div>
          <div className="kpi-value">{c.value}</div>
          <div className="kpi-sub">{c.sub}{c.delta}</div>
        </div>
      ))}
    </div>
  );
}

import type { SimConfig, SimResult } from "../types";
import KpiCards from "./KpiCards";
import QueueChart from "./QueueChart";
import StaffChart from "./StaffChart";
import PumpGantt from "./PumpGantt";
import WaitPanel from "./WaitPanel";
import StaffBuckets from "./StaffBuckets";
import EventLog from "./EventLog";

interface Props {
  result: SimResult;
  config: SimConfig;
  prevKpis: Record<string, number> | null;
}

export default function ResultsDashboard({ result, config, prevKpis }: Props) {
  return (
    <div className="dashboard">
      <KpiCards result={result} config={config} prevKpis={prevKpis} />

      {result.recommendations.length > 0 && (
        <section className="card">
          <h3>💡 调度建议</h3>
          <ul className="rec-list">
            {result.recommendations.map((r, i) => <li key={i}>{r}</li>)}
          </ul>
        </section>
      )}

      <section className="card">
        <h3>各油品车道排队长度（辆）</h3>
        <QueueChart result={result} config={config} />
      </section>

      <div className="two-col">
        <section className="card">
          <h3>人力负荷 vs 在岗人力</h3>
          <StaffChart result={result} config={config} />
        </section>
        <section className="card">
          <h3>15分钟人力需求与排班</h3>
          <StaffBuckets result={result} />
        </section>
      </div>

      <section className="card">
        <h3>油枪开闭时间线与利用率</h3>
        <PumpGantt result={result} config={config} />
      </section>

      <section className="card">
        <h3>等待时间分布与分油品统计</h3>
        <WaitPanel result={result} config={config} />
      </section>

      <section className="card">
        <h3>事件轨迹（可解释性日志）</h3>
        <EventLog result={result} />
      </section>
    </div>
  );
}
